window.kbPageData["views/entry/k-c99f0694b104fc82"] = {"key":"entry/k-c99f0694b104fc82","state":{"route":"entry/k-c99f0694b104fc82"},"node":{"id":"k-c99f0694b104fc82","mode":"k","title":"劳动者不能胜任工作的认定","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["认定劳动者不能胜任工作须结合任务和实际表现，绩效末位本身不足以认定"],"qs":["江苏 2023 B类 行测#12"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"用人单位认定劳动者不能胜任工作，应结合适用的岗位要求、劳动合同约定的任务和劳动者的实际完成情况。绩效排名末位本身不足以认定不能胜任工作。","review":{"definition":"用人单位认定劳动者不能胜任工作，应结合适用的岗位要求、劳动合同约定的任务和劳动者的实际完成情况。绩效排名末位本身不足以认定不能胜任工作。","explanation":"末位反映的是相对排名。即使同岗位人员都完成了要求的工作量，仍可能有人排在末位。题干仅给出王某连续两年末位的结果，未给出他未完成岗位任务的事实，因此D项的认定依据不足。","references":[],"evidence":"王某连续两个年度考核为末位","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 B类 行测#12":{"paper":"江苏 2023 B类 行测","n":12,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",2],"asrc":["b08f2713d73015eac675.pdf",5],"card":"8e66ce0a4bb20d071224c459","links":[{"id":"k-c99f0694b104fc82","role":"解题依据","why":"能否认定不能胜任工作关系到公司主张的解除事由能否成立。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-c99f0694b104fc82":[["江苏 2023 B类 行测#12"]]}};
